gameActivityOnCreateBeginningAdditions.insert:
// Tapping a local notification starts GameActivity directly, skipping SplashActivity, which is what passes
// the immersive and cutout settings on as extras. GameActivity reads them from any extras it gets, so the
// notification's own extras would turn immersive mode off (Back/Home/Recents stay on screen). Pass them on
// from the manifest here, as SplashActivity does.
if (!isStandalone && _extrasBundle != null && _extrasBundle.getString("UseSplashScreen") == null)
{
	try
	{
		Bundle HappinessMeta = getPackageManager().getApplicationInfo(getPackageName(), PackageManager.GET_META_DATA).metaData;
		if (HappinessMeta != null)
		{
			if (HappinessMeta.getBoolean("com.epicgames.unreal.GameActivity.bShouldHideUI", false))
			{
				_extrasBundle.putString("ShouldHideUI", "true");
			}
			if (HappinessMeta.getBoolean("com.epicgames.unreal.GameActivity.bUseDisplayCutout", false))
			{
				_extrasBundle.putString("UseDisplayCutout", "true");
			}
		}
	}
	catch (PackageManager.NameNotFoundException e)
	{
	}
}

gameActivityClassAdditions.insert:
/** UDailyReminderSubsystem: ask for permission to notify (Android 13+; earlier versions need none) */
public void AndroidThunkJava_Happiness_RequestNotifications()
{
	if (android.os.Build.VERSION.SDK_INT >= 33 &&
		checkSelfPermission("android.permission.POST_NOTIFICATIONS") != android.content.pm.PackageManager.PERMISSION_GRANTED)
	{
		runOnUiThread(new Runnable()
		{
			public void run()
			{
				requestPermissions(new String[] { "android.permission.POST_NOTIFICATIONS" }, 7301);
			}
		});
	}
}

/** UBackButtonSubsystem: the back button sends the app to the background, like Home */
public void AndroidThunkJava_Happiness_MoveToBack()
{
	runOnUiThread(new Runnable()
	{
		public void run()
		{
			moveTaskToBack(true);
		}
	});
}
